// ===== verifyOTPAndRegister =====
exports.verifyOTPAndRegister = onCall({ cors: CORS, region: REGION }, async (req) => {
  const { schoolId, studentCivilId, parentPhone, otp, password } = req.data;
  if (!schoolId || !studentCivilId || !parentPhone || !otp || !password) {
    throw new HttpsError("invalid-argument", "ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬آ¦ط·آ¸ط¸آ¹ط·آ·ط¢آ¹ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع‘ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ·ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ¨ط·آ·ط¢آ©");
  }
  const otpRef = db.collection("otp_requests").doc(schoolId + "_" + studentCivilId);
  return await db.runTransaction(async (t) => {
    const otpDoc = await t.get(otpRef);
    if (!otpDoc.exists) throw new HttpsError("not-found", "ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ ط·آ¸ط¸آ¹ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ·ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¨ OTP");
    const data = otpDoc.data();
    // ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬ع‘ ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬آ  OTP ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬آ¦ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ§ط·آ·ط¢آ±ط·آ¸أ¢â‚¬آ ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â€ڑآ¬ hash
    const crypto = require("crypto");
    const otpHash = crypto.createHash("sha256").update(otp).digest("hex");
    if (data.otpHash !== otpHash) throw new HttpsError("unauthenticated", "ط·آ·ط¢آ±ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ² ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¹آ¾ط·آ·ط¢آ­ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬ع‘ ط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ·ط¢آµط·آ·ط¢آ­ط·آ¸ط¸آ¹ط·آ·ط¢آ­");
    if (data.expiresAt.toDate() < new Date()) throw new HttpsError("deadline-exceeded", "ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬طŒط·آ·ط¹آ¾ ط·آ·ط¢آµط·آ¸أ¢â‚¬â€چط·آ·ط¢آ§ط·آ·ط¢آ­ط·آ¸ط¸آ¹ط·آ·ط¢آ© ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ±ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ²");
    if (data.parentPhone !== parentPhone) throw new HttpsError("permission-denied", "ط·آ·ط¢آ±ط·آ¸أ¢â‚¬ع‘ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬طŒط·آ·ط¢آ§ط·آ·ط¹آ¾ط·آ¸ط¸آ¾ ط·آ·ط·â€؛ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ·ط·آ·ط¢آ§ط·آ·ط¢آ¨ط·آ¸أ¢â‚¬ع‘");
    const passHash = await hashPassword(password);
    const parentRef = db.collection("parents").doc();
    t.set(parentRef, {
      schoolId,
      phone: parentPhone,
      studentDocId: data.studentDocId,
      studentCivilId,
      studentId: data.studentId || data.studentDocId,
      studentIds: [data.studentId || data.studentDocId],
      passHash,
      createdAt: admin.firestore.FieldValue.serverTimestamp()
    });
    t.delete(otpRef);
    return { success: true, parentId: parentRef.id };
  });
});
